import{_ as t,o as a,c as o,a2 as i}from"./chunks/framework.C8nVztS1.js";const u=JSON.parse('{"title":"Roadmap","description":"Path from 0.6 to a honest 1.0 — what is stable, what is missing, what stays optional.","frontmatter":{"title":"Roadmap","description":"Path from 0.6 to a honest 1.0 — what is stable, what is missing, what stays optional.","outline":"deep"},"headers":[],"relativePath":"roadmap.md","filePath":"roadmap.md","lastUpdated":1789828988000}'),r={name:"roadmap.md"};function s(d,e,n,l,c,p){return a(),o("div",null,[...e[0]||(e[0]=[i('<h1 id="roadmap" tabindex="-1">Roadmap <a class="header-anchor" href="#roadmap" aria-label="Permalink to &quot;Roadmap&quot;">​</a></h1><p>Current line: <strong>0.6.x</strong> (pre-1.0). Theme: <strong>honest consumer path</strong> — init → install → e2e, overrides in CI, peers match docs. <strong>1.0</strong> means a clear <a href="/untestutils/guide/support-matrix">support matrix</a> and no silent gaps between docs and CI.</p><h2 id="stable-now-0-6" tabindex="-1">Stable now (0.6) <a class="header-anchor" href="#stable-now-0-6" aria-label="Permalink to &quot;Stable now (0.6)&quot;">​</a></h2><ul><li>Recipe contract: prepare → start → URL/dir, shared identity cache under <code>.untestutils</code></li><li>Vitest plugin + Playwright <code>createPlaywrightConfig</code>, same <code>recipes.ts</code></li><li>Drivers: <code>staticDir</code>, <code>command</code>, <code>nodeEntry</code>, <code>host</code>, <code>nuxt({ run })</code></li><li>Framework dogfood in CI: Vite, Next, Astro, SvelteKit, Remix, SolidStart (+ static)</li><li>Typed config overrides in CI (<code>viteConfig</code> / <code>nextConfig</code> / <code>kitConfig</code> / …)</li><li>Nuxt unit (<code>environment: &#39;untestutils&#39;</code>) in playground CI (<code>test:playground:unit</code>)</li><li>CLI <code>init</code> / <code>doctor</code> / <code>doctor --recipes</code> + temp-dir dogfood (<code>test:cli-dogfood</code>)</li><li>Node <strong>22</strong> primary CI + <strong>Node 20</strong> smoke (<code>test:unit</code> + <code>test:pack</code>)</li><li>Utils for live checks (cookies, SEO, redirects, poll)</li><li>Scoped emit-only publish: <code>@untestutils/*</code> + thin <code>untestutils</code> facade; lockstep semver</li><li>Docs site (this)</li></ul><p>Use the <strong>same version</strong> for facade and any <code>@untestutils/*</code> adapter you install.</p><h3 id="migration-note-0-6" tabindex="-1">Migration note (0.6) <a class="header-anchor" href="#migration-note-0-6" aria-label="Permalink to &quot;Migration note (0.6)&quot;">​</a></h3><p><code>@untestutils/nuxt</code> and <code>vitest-environment-untestutils</code> are <strong>optional peers</strong> (no longer hard deps of the facade). Nuxt users:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> add</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -D</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> untestutils</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> @untestutils/nuxt</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> vitest-environment-untestutils</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> nuxt</span></span></code></pre></div><h2 id="before-1-0" tabindex="-1">Before 1.0 <a class="header-anchor" href="#before-1-0" aria-label="Permalink to &quot;Before 1.0&quot;">​</a></h2><p>Ordered by impact. Full table: <a href="/untestutils/guide/support-matrix">Support matrix</a>.</p><h3 id="_1-support-matrix-docs-ci" tabindex="-1">1. Support matrix (docs + CI) <a class="header-anchor" href="#_1-support-matrix-docs-ci" aria-label="Permalink to &quot;1. Support matrix (docs + CI)&quot;">​</a></h3><p>Keep <strong>stable</strong> vs <strong>experimental</strong> vs <strong>optional</strong> honest as features land.</p><table tabindex="0"><thead><tr><th>Area</th><th>Today</th><th>1.0 bar</th></tr></thead><tbody><tr><td>Vitest / Playwright e2e</td><td>Stable, in CI</td><td>Keep</td></tr><tr><td>Nuxt server recipes</td><td>Stable, unit/driver covered</td><td>Keep</td></tr><tr><td>Vite / Next / Astro / SvelteKit / Remix / SolidStart</td><td>Dogfood in playground CI</td><td>Keep</td></tr><tr><td>Nuxt unit</td><td>Documented + <code>test:playground:unit</code> in CI</td><td>Keep</td></tr><tr><td>CLI scaffolding</td><td>Dogfood in CI</td><td>Keep</td></tr><tr><td>AI codegen</td><td>Optional, mock in CI</td><td>Stay optional (labeled)</td></tr><tr><td>Perf suite</td><td>Unit + optional <code>workflow_dispatch</code> dogfood</td><td>Stay optional (labeled)</td></tr></tbody></table><h3 id="_2-package-hygiene" tabindex="-1">2. Package hygiene <a class="header-anchor" href="#_2-package-hygiene" aria-label="Permalink to &quot;2. Package hygiene&quot;">​</a></h3><ul><li>Clearer peer signal for Vitest as primary consumer (doctor checks majors 4|5)</li><li>Slimmer facade (optional peers for nuxt / ai / perf) — done in 0.6</li></ul><h3 id="_3-typecheck-surface" tabindex="-1">3. Typecheck surface <a class="header-anchor" href="#_3-typecheck-surface" aria-label="Permalink to &quot;3. Typecheck surface&quot;">​</a></h3><p>Root <code>typecheck</code> should cover facade-critical packages (<code>nuxt</code> unit subpaths as needed) so published <code>.d.ts</code> do not drift.</p><h3 id="_4-semver-promise" tabindex="-1">4. Semver promise <a class="header-anchor" href="#_4-semver-promise" aria-label="Permalink to &quot;4. Semver promise&quot;">​</a></h3><p>Ship <strong>1.0.0</strong> with the matrix above, changelog that states stable vs optional, and no “documented as supported but untested in CI” drivers.</p><h2 id="after-1-0" tabindex="-1">After 1.0 <a class="header-anchor" href="#after-1-0" aria-label="Permalink to &quot;After 1.0&quot;">​</a></h2><ul><li>WebKit in Playwright CI (optional job)</li><li>Richer framework fixtures as demand appears</li><li>Live-LLM AI smoke (mock stays CI default)</li><li>Vitest Browser Mode as a separate optional track (not recipe-e2e)</li></ul><h2 id="explore-pre-release-—-decided" tabindex="-1">Explore (pre-release — decided) <a class="header-anchor" href="#explore-pre-release-—-decided" aria-label="Permalink to &quot;Explore (pre-release — decided)&quot;">​</a></h2><p>Spike: <strong>faster</strong> browser backends for mass recipe e2e. Out of scope for 1.0 — details: <a href="/untestutils/guide/explore-browsers">Explore — alternate browsers</a>.</p><table tabindex="0"><thead><tr><th>Project</th><th>Verdict</th></tr></thead><tbody><tr><td>Astral</td><td>Skip for 1.0 — Deno-only; no Node/Vitest path</td></tr><tr><td>Thirtyfour</td><td>Skip for 1.0 — WebDriver + Node bridge; unclear perf win</td></tr><tr><td>Chromiumoxide</td><td>Skip for 1.0 — Rust CDP is the interesting perf bet; deferred for integration cost (not “Playwright already does CDP”)</td></tr></tbody></table><p>Vitest Browser Mode is a <strong>separate</strong> optional track — not recipe-e2e. See <a href="/untestutils/guide/browser-mode">Browser Mode</a>.</p><p><code>@nuxt/test-utils</code> extras (<code>$fetchComponent</code>, full browser render API) stay deferred until real dogfood — not 1.0 goals.</p><h2 id="not-goals-for-1-0" tabindex="-1">Not goals for 1.0 <a class="header-anchor" href="#not-goals-for-1-0" aria-label="Permalink to &quot;Not goals for 1.0&quot;">​</a></h2><ul><li>Replacing Vitest or Playwright</li><li>Drop-in compatibility with <code>@nuxt/test-utils</code></li><li>Shipping a second browser stack before Chromiumoxide proves a win</li></ul><h2 id="next" tabindex="-1">Next <a class="header-anchor" href="#next" aria-label="Permalink to &quot;Next&quot;">​</a></h2><ul><li><a href="/untestutils/guide/support-matrix">Support matrix</a></li><li><a href="/untestutils/guide/getting-started">Getting started</a></li></ul>',30)])])}const g=t(r,[["render",s]]);export{u as __pageData,g as default};
